CREATE TEMP TABLE lib_migration (id bigint PRIMARY KEY, new_guid text, new_path text);
;
UPDATE media_items m SET guid = l.new_guid::uuid, path = l.new_path FROM lib_migration l WHERE m.id = l.id;
UPDATE media_items m SET top_parent_id = l.new_guid FROM lib_migration l JOIN ancestor_ids a ON a.ancestor_id = l.id WHERE a.item_id = m.id;
UPDATE media_items SET guid = 'f27caa37-e514-2225-cced-ed48f6553502'::uuid, path = 'D:\OpenMedia-8098\ProgramData-Server\root' WHERE type = 24;
SELECT 'libs migrated' AS check, count(*) FROM lib_migration;
SELECT 'top_parent updated' AS check, count(*) FROM media_items WHERE top_parent_id IN (SELECT new_guid FROM lib_migration);
